private val gitSteps=listOf("Read ticket + acceptance criteria","git switch -c feature/login-validation","git status","git add .","git commit -m \"feat: add login validation\"","git log","git push origin feature/login-validation","Open Pull Request","Read CI failure and fix root cause","Review comments + merge")

@Composable fun PathPilotFullApp(vm:PathPilotViewModel){var screen by remember{mutableStateOf("home")};var selected by remember{mutableStateOf<Course?>(null)};var project by remember{mutableStateOf<Project?>(null)};BackHandler(enabled=screen!="home"){screen="home"};Surface(Modifier.fillMaxSize(),Color(0xFFF7FAFF)){when(screen){"home"->Home({screen="learn"},{screen="projects"},{screen="git"},{screen="mentor"},{screen="college"});"learn"->Learn({selected=it;screen="course"}){screen="home"};"course"->selected?.let{CourseScreen(it){screen="learn"}};"projects"->Projects({project=it;screen="project"}){screen="home"};"project"->project?.let{ProjectScreen(it){screen="projects"}};"git"->GitLab{screen="home"};"mentor"->Mentor{screen="home"};else->College{screen="home"}}}}

@Composable private fun Header(title:String,onBack:(()->Unit)?=null){Row(Modifier.fillMaxWidth().padding(15.dp),verticalAlignment=Alignment.CenterVertically){if(onBack!=null)IconButton(onBack){Icon(Icons.Default.ArrowBack,"Back")};Box(Modifier.size(43.dp).background(Blue,RoundedCornerShape(13.dp)),contentAlignment=Alignment.Center){Text("➤",color=Color.White,fontSize=23.sp,fontWeight=FontWeight.Black)};Spacer(Modifier.width(9.dp));Column{Text(title,fontSize=21.sp,fontWeight=FontWeight.Black,color=Navy);Text("AI Engineering Academy",fontSize=9.sp,color=Gray)}}}

@Composable private fun Home(learn:()->Unit,projects:()->Unit,git:()->Unit,mentor:()->Unit,college:()->Unit){val p=LocalContext.current.getSharedPreferences("pathpilot_engine",Context.MODE_PRIVATE);val done=courses.count{p.getBoolean("done_${it.id}",false)};LazyColumn(contentPadding=PaddingValues(bottom=25.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Header()};item{Column(Modifier.padding(horizontal=18.dp)){Text("Learn. Build. Debug. Ship.",fontSize=28.sp,fontWeight=FontWeight.Black,color=Navy);Text("A practical engineering academy — not a flashcard app.",fontSize=12.sp,color=Gray)}};item{Card(Modifier.padding(horizontal=18.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Soft),shape=RoundedCornerShape(22.dp)){Column(Modifier.padding(20.dp)){Text("TODAY'S PATH",fontSize=10.sp,color=Blue,fontWeight=FontWeight.Black);Text("LEARN → LAB → BUILD → DEBUG → REVIEW",fontSize=18.sp,fontWeight=FontWeight.Black,color=Navy,modifier=Modifier.padding(top=5.dp));Text("Every skill ends in real work and a reviewable outcome.",fontSize=12.sp,color=Gray,modifier=Modifier.padding(top=5.dp))}}};item{Card(Modifier.padding(horizontal=18.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp)){Row{Text("Academy progress",fontWeight=FontWeight.Black,color=Navy,modifier=Modifier.weight(1f));Text("$done/${courses.size}",color=Blue,fontWeight=FontWeight.Bold)};LinearProgressIndicator({done.toFloat()/courses.size},Modifier.fillMaxWidth().padding(top=8.dp),color=Blue)}}};item{Row(Modifier.padding(horizontal=18.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){Tile(Icons.Default.Code,"Learn",Soft,learn);Tile(Icons.Default.Folder,"Projects",Green,projects);Tile(Icons.Default.Terminal,"Git Lab",Purple,git)}};item{Row(Modifier.padding(horizontal=18.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){Tile(Icons.Default.Psychology,"AI Mentor",Purple,mentor);Tile(Icons.Default.School,"College",Orange,college)}};item{Text("Professional workflow",Modifier.padding(horizontal=18.dp),fontSize=18.sp,fontWeight=FontWeight.Black,color=Navy)};item{Text("Requirement → ticket → branch → code → test → commit → PR → review → CI → deploy → security → postmortem.",Modifier.padding(horizontal=18.dp),fontSize=12.sp,color=Gray)}}}
@Composable private fun RowScope.Tile(icon:androidx.compose.ui.graphics.vector.ImageVector,title:String,bg:Color,onClick:()->Unit){Card(Modifier.weight(1f).clickable(onClick=onClick),colors=CardDefaults.cardColors(bg),shape=RoundedCornerShape(15.dp)){Column(Modifier.padding(13.dp)){Icon(icon,null,tint=Blue);Spacer(Modifier.height(5.dp));Text(title,fontSize=11.sp,fontWeight=FontWeight.Bold,color=Navy)}}}

@Composable private fun Learn(open:(Course)->Unit,back:()->Unit){var q by remember{mutableStateOf("")};var cat by remember{mutableStateOf("All")};val cats=listOf("All","Programming","Web","Backend","Professional","AI","Cybersecurity","Architecture","Agency","Capstone");val list=courses.filter{(cat=="All"||it.cat==cat)&&(q.isBlank()||it.name.contains(q,true)||it.concept.contains(q,true))};LazyColumn(contentPadding=PaddingValues(bottom=25.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){item{Header("Learn",back)};item{OutlinedTextField(q,{q=it},Modifier.padding(horizontal=16.dp).fillMaxWidth(),singleLine=true,label={Text("Search skill")})};item{Row(Modifier.horizontalScroll(rememberScrollState()).padding(horizontal=16.dp),horizontalArrangement=Arrangement.spacedBy(6.dp)){cats.forEach{Surface(Modifier.clickable{cat=it},shape=RoundedCornerShape(18.dp),color=if(cat==it)Blue else Color.White){Text(it,Modifier.padding(horizontal=11.dp,vertical=7.dp),fontSize=10.sp,color=if(cat==it)Color.White else Gray)}}}};items(list){c->Card(Modifier.padding(horizontal=16.dp).fillMaxWidth().clickable{open(c)},colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(16.dp)){Column(Modifier.padding(15.dp)){Text("${c.cat} • ${c.level}",fontSize=9.sp,color=Blue,fontWeight=FontWeight.Bold);Text(c.name,fontSize=16.sp,fontWeight=FontWeight.Black,color=Navy);Text(c.concept,fontSize=11.sp,color=Gray,modifier=Modifier.padding(top=4.dp));Text("Open journey →",fontSize=10.sp,color=Blue,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=7.dp))}}}}}

@Composable private fun CourseScreen(c:Course,back:()->Unit){var phase by remember{mutableIntStateOf(0)};val names=listOf("LEARN","LAB","BUILD","DEBUG","REVIEW");val text=listOf(c.concept,c.mission,c.build,c.debug,c.review);LazyColumn(contentPadding=PaddingValues(bottom=25.dp),verticalArrangement=Arrangement.spacedBy(11.dp)){item{Header(c.name,back)};item{Row(Modifier.horizontalScroll(rememberScrollState()).padding(horizontal=16.dp),horizontalArrangement=Arrangement.spacedBy(6.dp)){names.forEachIndexed{i,n->Surface(Modifier.clickable{phase=i},shape=RoundedCornerShape(18.dp),color=if(i==phase)Blue else Color.White){Text(n,Modifier.padding(horizontal=12.dp,vertical=7.dp),fontSize=10.sp,color=if(i==phase)Color.White else Gray)}}}};item{Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(20.dp)){Column(Modifier.padding(18.dp)){Text(names[phase],fontSize=10.sp,color=Blue,fontWeight=FontWeight.Black);Text(text[phase],fontSize=20.sp,fontWeight=FontWeight.Black,color=Navy,modifier=Modifier.padding(top=5.dp));Text("Do the work. PathPilot gives hints and review criteria, not a copy-paste solution.",fontSize=12.sp,color=Gray,modifier=Modifier.padding(top=7.dp));Button({if(phase<4)phase++else LocalContext.current.getSharedPreferences("pathpilot_engine",Context.MODE_PRIVATE).edit().putBoolean("done_${c.id}",true).apply()},Modifier.fillMaxWidth().padding(top=11.dp),shape=RoundedCornerShape(12.dp)){Text(if(phase<4)"Complete phase" else "Complete course")}}}};item{Text("Evidence to keep",Modifier.padding(horizontal=18.dp),fontWeight=FontWeight.Black,color=Navy)};item{Text("Requirements • branch • commits • tests • PR • review comments • deployment notes • security check • README.",Modifier.padding(horizontal=18.dp),fontSize=12.sp,color=Gray)}}}

@Composable private fun Projects(open:(Project)->Unit,back:()->Unit){LazyColumn(contentPadding=PaddingValues(bottom=25.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Header("Project Room",back)};item{Text("Finish complete products, not toy demos.",Modifier.padding(horizontal=18.dp),fontSize=23.sp,fontWeight=FontWeight.Black,color=Navy)};items(projects){p->Card(Modifier.padding(horizontal=16.dp).fillMaxWidth().clickable{open(p)},colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(17.dp)){Text(p.name,fontSize=17.sp,fontWeight=FontWeight.Black,color=Navy);Text(p.stack,fontSize=10.sp,color=Blue,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=4.dp));Text(p.brief,fontSize=12.sp,color=Gray,modifier=Modifier.padding(top=5.dp));Text("${p.steps.size} production milestones →",fontSize=10.sp,color=Blue,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=8.dp))}}}}}
@Composable private fun ProjectScreen(p:Project,back:()->Unit){var done by remember{mutableStateOf(setOf<Int>())};val progress=done.size.toFloat()/p.steps.size;LazyColumn(contentPadding=PaddingValues(bottom=25.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Header(p.name,back)};item{Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Soft),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp)){Text(p.stack,fontSize=10.sp,color=Blue,fontWeight=FontWeight.Bold);Text(p.brief,fontSize=13.sp,fontWeight=FontWeight.Bold,color=Navy,modifier=Modifier.padding(top=4.dp));LinearProgressIndicator({progress},Modifier.fillMaxWidth().padding(top=9.dp),color=Blue)}}};items(p.steps.indices.toList()){i->val yes=i in done;Card(Modifier.padding(horizontal=16.dp).fillMaxWidth().clickable{done=if(yes)done-i else done+i},colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(14.dp)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Icon(if(yes)Icons.Default.CheckCircle else Icons.Default.Build,null,tint=if(yes)Color(0xFF138A52) else Blue);Spacer(Modifier.width(9.dp));Column{Text("Milestone ${i+1}",fontSize=9.sp,color=Blue,fontWeight=FontWeight.Bold);Text(p.steps[i],fontSize=12.sp,fontWeight=FontWeight.Bold,color=Navy)}}}};item{Text("Definition of Done: working code + tests + clean Git history + PR review + deployment + security + README.",Modifier.padding(horizontal=18.dp),fontSize=11.sp,color=Gray)}}}

@Composable private fun GitLab(back:()->Unit){var i by remember{mutableIntStateOf(0)};var input by remember{mutableStateOf("")};var result by remember{mutableStateOf("")};val expected=gitSteps[i].lowercase();LazyColumn(contentPadding=PaddingValues(bottom=25.dp),verticalArrangement=Arrangement.spacedBy(11.dp)){item{Header("Git + GitHub Practice",back)};item{Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Navy),shape=RoundedCornerShape(20.dp)){Column(Modifier.padding(18.dp)){Text("TICKET → BRANCH → COMMIT → PR → CI → REVIEW → MERGE",fontSize=10.sp,color=Soft,fontWeight=FontWeight.Black);Text("Real developer workflow",fontSize=22.sp,color=Color.White,fontWeight=FontWeight.Black);LinearProgressIndicator({i.toFloat()/gitSteps.size},Modifier.fillMaxWidth().padding(top=10.dp),color=Blue)}}};item{Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(17.dp)){Text("Step ${i+1}: ${gitSteps[i]}",fontSize=18.sp,fontWeight=FontWeight.Black,color=Navy);Text("Enter the command/action you would use. This simulator teaches the workflow; later it can be connected to a real GitHub repository.",fontSize=11.sp,color=Gray,modifier=Modifier.padding(top=5.dp));OutlinedTextField(input,{input=it},Modifier.fillMaxWidth().padding(top=9.dp),singleLine=true,label={Text("Command / action")});Button({val ok=input.trim().lowercase()==expected||expected=="git add ."&&input.trim().lowercase().startsWith("git add ");result=if(ok)"✓ Correct — next step unlocked." else "Try again — use the Git concept from the step.";if(ok&&i<gitSteps.lastIndex){i++;input=""}},Modifier.fillMaxWidth().padding(top=8.dp),shape=RoundedCornerShape(12.dp)){Text("Check")};if(result.isNotBlank())Text(result,fontSize=11.sp,color=if(result.startsWith("✓"))Color(0xFF138A52) else Color(0xFFC2410C),modifier=Modifier.padding(top=7.dp))}}};items(gitSteps){s->Text("• $s",Modifier.padding(horizontal=20.dp),fontSize=11.sp,color=Gray)}}

@Composable private fun Mentor(back:()->Unit){var q by remember{mutableStateOf("")};var answer by remember{mutableStateOf("")};var loading by remember{mutableStateOf(false)};val scope=rememberCoroutineScope();val ctx=LocalContext.current;LazyColumn(contentPadding=PaddingValues(bottom=25.dp),verticalArrangement=Arrangement.spacedBy(11.dp)){item{Header("AI Mentor",back)};item{Text("Ask a senior engineer. Learn the reasoning, then do the next action.",Modifier.padding(horizontal=18.dp),fontSize=22.sp,fontWeight=FontWeight.Black,color=Navy)};item{OutlinedTextField(q,{q=it},Modifier.padding(horizontal=16.dp).fillMaxWidth().heightIn(min=120.dp),label={Text("What are you stuck on?")});Button({if(q.isNotBlank()){loading=true;scope.launch{answer=try{GeminiMentorService.askGeminiMentor(ctx,q,"PathPilot learner. Teach first, ask for evidence, give one next action.")}catch(e:Exception){"Mentor error: ${e.message}"};loading=false}}},Modifier.padding(horizontal=16.dp).fillMaxWidth(),enabled=q.isNotBlank()&&!loading,shape=RoundedCornerShape(12.dp)){Text(if(loading)"Thinking…" else "Ask Gemini")}};if(answer.isNotBlank())item{Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(18.dp)){Text(answer,Modifier.padding(17.dp),fontSize=12.sp,color=Navy)}}}}

